INSERT OR REPLACE INTO site_config (key, value) VALUES (
  'reading_tab_intros',
  '{"latest":"Over the past month, Rommy''s reading has leaned hard into Mediterranean and European littoral fiction — quiet, place-saturated books where landscape and memory do as much work as plot. In July that meant Isabel Allende''s generational Chile (<em>The House of the Spirits</em>), Greek coming-of-age and village life (<em>Three Summers</em>, <em>When the Tree Sings</em>, <em>The Murderess</em>), Jean Giono''s pastoral Provence (<em>Hill</em>), and Patrick Modiano''s spectral Paris (<em>In the Café of Lost Youth</em>); in June, Mercè Rodoreda''s seaside Catalonia (<em>Garden by the Sea</em>) and Leonora Carrington''s surrealism (<em>The Stone Door</em>). Nothing on the recent list is Anglo-American frontlist fiction — it is all translated or international, mostly mid-length, and tuned to mood, exile, and the texture of a specific world. Lately he seems to be chasing atmosphere and cultural rootedness more than narrative velocity.","mustReads":"Rommy''s Must Reads list reads like a personal canon of literary fiction that favors translation, rediscovery, and depth over novelty. It is anchored in Latin American and European voices — García Márquez, Bolaño, Cortázar, Rulfo, Allende, Kundera, Bulgakov, Modiano — alongside American masters of moral weight and atmosphere (McCarthy, McCullers, Baldwin, Capote, <em>Stoner</em>). NYRB Classics and small-press sensibilities show up again and again: <em>Butcher''s Crossing</em>, <em>Hard Rain Falling</em>, <em>Moravagine</em>, <em>The Door</em>, <em>The Murderess</em>. The list also reaches outward — Greek (<em>Three Summers</em>, <em>When the Tree Sings</em>), Japanese (<em>No Longer Human</em>, <em>Kafka on the Shore</em>), Arabic (<em>Woman at Point Zero</em>, <em>French Perfume</em>, <em>The Diesel</em>) — and makes room for a few outliers (<em>Jitterbug Perfume</em>, <em>In Cold Blood</em>, <em>The Great Bridge</em>) that share the same appetite for voice, place, and consequence. Overall, the taste is serious but not solemn: psychologically rich, often regional or outsider-centered, and allergic to bestseller churn."}'
);
